import requests

SUPPLIER_URL = "https://supplier.example.org/api/deliveries"


def fetch_deliveries(token: str) -> requests.Response:
    """Fetch the delivery list. token comes from dbutils.secrets.get at run time."""
    return requests.get(SUPPLIER_URL, headers={"Authorization": f"Bearer {token}"}, timeout=30)
